public class BooleanOptionHandler_parseArguments_TriageGen2Test {

    @Mock
    private Setter<Boolean> setter;

    @Mock
    private Parameters params;

    // Note: Since OptionDef and CmdLineParser are required for the constructor 
    // but not used in the method logic, we mock them.
    @Mock
    private com.google.javascript.jscomp.CommandLineRunner.Flags.OptionDef optionDef;
    @Mock
    private com.google.javascript.jscomp.CommandLineRunner.Flags.CmdLineParser cmdLineParser;

    private BooleanOptionHandler handler;

    // These constants are assumed to be part of the class logic based on the provided snippet
    private static final List<String> TRUES = Arrays.asList("true", "yes", "on");
    private static final List<String> FALSES = Arrays.asList("false", "no", "off");

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // We create an anonymous subclass or use the real one if possible.
        // Since we cannot modify the original class constants TRUES/FALSES in this test scope
        // if they are private, this test assumes the environment matches the provided logic.
        handler = new BooleanOptionHandler(cmdLineParser, optionDef, setter) {
            // If TRUES/FALSES are not accessible, this test structure assumes they are 
            // accessible or part of the class being tested.
        };
    }

    @Test
    public void testParseArguments_NullParam() throws Exception {
        when(params.getParameter(0)).thenReturn(null);

        int result = handler.parseArguments(params);

        assertEquals(0, result);
        verify(setter).addValue(true);
    }

    @Test
    public void testParseArguments_TrueValue() throws Exception {
        // Testing "true" (lowercase)
        when(params.getParameter(0)).thenReturn("true");

        int result = handler.parseArguments(params);

        assertEquals(1, result);
        verify(setter).addValue(true);
    }

    @Test
    public void testParseArguments_TrueValueMixedCase() throws Exception {
        // Testing "TRUE" (case sensitivity check)
        when(params.getParameter(0)).thenReturn("TRUE");

        int result = handler.parseArguments(params);

        assertEquals(1, result);
        verify(setter).addValue(true);
    }

    @Test
    public void testParseArguments_FalseValue() throws Exception {
        // Testing "false"
        when(params.getParameter(0)).thenReturn("false");

        int result = handler.parseArguments(params);

        assertEquals(1, result);
        verify(setter).addValue(false);
    }

    @Test
    public void testParseArguments_FalseValueMixedCase() throws Exception {
        // Testing "fAlSe"
        when(params.getParameter(0)).thenReturn("fAlSe");

        int result = handler.parseArguments(params);

        assertEquals(1, result);
        verify(setter).addValue(false);
    }

    @Test
    public void testParseArguments_InvalidValue() throws Exception {
        // Testing an unrecognized string
        when(params.getParameter(0)).thenReturn("maybe");

        int result = handler.parseArguments(params);

        assertEquals(0, result);
        verify(setter).addValue(true);
    }
}
